sys_script_include.script:
var RaaSUtils = Class.create();
RaaSUtils.prototype = {
    initialize: function() {},
    refQualMedia: function() {
        var moviesNotToBeShown = [];

        var grReview = new GlideRecord("x_1488662_raas_review");
        grReview.addQuery('state', '!=', '4');
        grReview.addQuery("opened_by", gs.getUserID()); // Use sys_id for filtering
        // grReview.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state!=4");
        grReview.query();
        while (grReview.next()) {
            moviesNotToBeShown.push(grReview.media.sys_id.toString());
        }

        var moviesToBeShown = [];
        var grMedias = new GlideRecord("x_1488662_raas_media");
        grMedias.addQuery("state", "3");
        grMedias.query();
        while (grMedias.next()) {
            if (moviesNotToBeShown.indexOf(grMedias.getUniqueValue()) == -1) {
                moviesToBeShown.push(grMedias.getUniqueValue());
            }
        }

        return "sys_idIN" + moviesToBeShown.join(",");
    },
    type: 'RaaSUtils'
};
